    var rxfuncstr = rxstr[1].split(":");
    if (rxfuncstr[1] == "ERR") {
        commandOK = 1;
        if (rxfuncstr[0] == "CMD") {
            comOK = 0;
        } else if (rxfuncstr[0] == "CH") {
            chOK = 0;
        } else if (rxfuncstr[0] == "PAR") {
            parOK = 0;
