            valOK = 0;
        } else if (rxfuncstr[0] == "LOC") {
            remoteOK = 0;
        }
    } else if (rxfuncstr[1] == "OK") {
        commandOK = 1;
        if (rxstr.length > 2 && rxstr[2] != "") {
            var valstr = rxstr[2].split(":");
            if (valstr.length > 1) {
                valch = valstr[1].split(";");
            }
        }
    }
}

